#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using MVZ2Logic.Entities;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.playDeathSound)]
    public class PlayDeathSoundBehaviour : EntityBehaviourDefinition
    {
        public PlayDeathSoundBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        public override void PostDeath(Entity entity, DeathInfo damageInfo)
        {
            base.PostDeath(entity, damageInfo);
            if (entity.WillRemoveOnDeath(damageInfo))
            {
                return;
            }
            entity.PlayDeathSound();
        }
    }
}